test('independent sections use local pagination, exact role counts, and one explicit expansion', async () => {
    const h = harness();
    h.controller.start();
    await until(() => h.controller.sections.types.status === 'ready' && h.controller.sections.outgoing.count === '9007199254741000');
    assert.equal(h.controller.sections.types.rows.length, 40);
    const before = h.requests.length;
    await h.controller.page('types', 'next');
    assert.equal(h.controller.sections.types.rows[0][0].value, 'urn:value:40');
    assert.equal(h.requests.length, before, 'local page changes do not fetch');
    await h.controller.expand('types');
    const section = h.controller.sections.types;
    assert.equal(section.totalRows, 10002);
    assert.equal(section.expanded, true);
    assert.equal(section.start, 40, 'reusable rows preserve page position');
    assert.deepEqual(Array.from((await section.store.read(9999, 3)), item => item[0].value),
        ['urn:value:9999', 'urn:value:10000', 'urn:value:10001']);
    assert.equal(h.requests.filter(url => url.searchParams.get('section') === 'types'
        && url.searchParams.get('load') === 'more').length, 1);
    await h.controller.expand('types');
    assert.equal(h.requests.filter(url => url.searchParams.get('load') === 'more').length, 1);
    h.controller.dispose();
});

