test('a joined 10,000 plus five snapshot reads its last page from a spilled suffix', async () => {
    const budget = stream.createRowStoreBudget(16 * 1024 * 1024);
    const workers = [];
    const createStore = () => stream.createRowStore({ memoryBudget: budget, spillRowLimit: 0,
        workerFactory() { const worker = new MemoryWorker(); workers.push(worker); return worker; },
        storageTimeout: 1000 });
    const initialRows = Array.from({ length: 10000 }, (_, index) => row(index));
    const suffixRows = Array.from({ length: 5 }, (_, index) => row(10000 + index));
    const initial = await createStore();
    await initial.append(initialRows);
    await until(() => !initial.inMemory);
    const suffix = await createStore();
    await suffix.append(suffixRows);
    await until(() => !suffix.inMemory);
    const h = harness({ memoryBudget: budget, load: async ({ section, kind, load, options }) => {
        if (section !== 'outgoing' || kind !== 'rows') return;
        if (load === 'initial') return { rowStore: initial, rowCount: 10000, vars: ['value'], metadata: {} };
        assert.equal((await options.filterRows(suffixRows)).length, 5);
        return { rowStore: suffix, rowCount: 5, vars: ['value'], metadata: {} };
    } });
    h.controller.start();
    await until(() => h.controller.sections.outgoing.status === 'ready');
    await h.controller.expand('outgoing');
    const section = h.controller.sections.outgoing;
    assert.equal(section.expanded, true);
    assert.equal(section.totalRows, 10005);
    for (let page = 0; page < 100; page++) await h.controller.page('outgoing', 'next');
    assert.equal(section.start, 10000);
    assert.deepEqual(Array.from(section.rows, item => item[0].value),
        ['urn:value:10000', 'urn:value:10001', 'urn:value:10002', 'urn:value:10003', 'urn:value:10004']);
    assert.ok(workers[1].messages.some(message => message.op === 'read' && message.start === 0 && message.count === 5),
        'the page read reaches the spilled suffix with the available row count');
    const beyond = await section.store.readOwned(10005, 100);
    assert.equal(beyond.rows.length, 0);
    beyond.release();
    h.controller.dispose();
    await until(() => budget.usedBytes === 0);
});

