test('overlapping row retries keep only the newest result and dispose superseded stores', async () => {
    const pending = [];
    let intercept = false;
    const h = harness({ load: ({ section, kind, load }) => {
        if (intercept && section === 'types' && kind === 'rows' && load === 'initial') {
            return new Promise(resolve => pending.push(resolve));
        }
    } });
    h.controller.start();
    await until(() => h.controller.sections.types.status === 'ready');
    const original = h.controller.sections.types.store;
    intercept = true;
    const first = h.controller.retry('types', 'rows');
    await until(() => pending.length === 1);
    const second = h.controller.retry('types', 'rows');
    await until(() => pending.length === 2);
    const oldAnswer = store([row('old')]);
    const newAnswer = store([row('new')]);
    pending[1]({ rowStore: newAnswer, rowCount: 1, vars: ['value'], metadata: {} });
    await second;
    pending[0]({ rowStore: oldAnswer, rowCount: 1, vars: ['value'], metadata: {} });
    await first;
    assert.equal(h.controller.sections.types.rows[0][0].value, 'urn:value:new');
    assert.equal(original.disposed, true);
    assert.equal(oldAnswer.disposed, true);
    h.controller.dispose();
});

test('a newer retry aborts and cancels its stale server request', async () => {
    const pending = [];
    const cancelled = [];
    let intercept = false;
    const h = harness({ load: ({ section, kind, load, signal, url }) => {
        if (intercept && section === 'types' && kind === 'rows' && load === 'initial') {
            return new Promise(resolve => pending.push({ resolve, signal, id: url.searchParams.get('query-request-id') }));
        }
    }, cancel: id => cancelled.push(id) });
    h.controller.start();
    await until(() => h.controller.sections.types.status === 'ready');
    intercept = true;
    const first = h.controller.retry('types', 'rows');
    await until(() => pending.length === 1);
    const second = h.controller.retry('types', 'rows');
    await until(() => pending.length === 2);
    assert.equal(pending[0].signal.aborted, true);
    assert.ok(cancelled.includes(pending[0].id));
    pending[1].resolve({ rowStore: store([row('new')]), rowCount: 1, vars: ['value'], metadata: {} });
    pending[0].resolve({ rowStore: store([row('old')]), rowCount: 1, vars: ['value'], metadata: {} });
    await Promise.all([first, second]);
    h.controller.dispose();
});

test('uncertified replacement does not require an identity worker and awaits old-store cleanup', async () => {
    const pending = {};
    const h = harness({ createIdentityIndex: () => { throw new Error('worker unavailable'); } });
    h.initial[0] = [{ kind: 'bnode', value: 'unverified', scope: 'response' }];
    h.controller.start();
    await until(() => h.controller.sections.types.status === 'ready');
    const old = h.controller.sections.types.store;
    old.dispose = () => new Promise(resolve => { pending.store = resolve; });
    let settled = false;
    const expansion = h.controller.expand('types').then(() => { settled = true; });
    await until(() => !!pending.store);
    assert.equal(settled, false, 'the replaced store must be disposed before completion');
    pending.store();
    await expansion;
    assert.equal(h.controller.sections.types.expanded, true);
    h.controller.dispose();
});

