test('visible and staged windows remain owned until successful swap or route disposal', async () => {
    const initialRows = Array.from({ length: 10000 }, (_, index) => row(index));
    initialRows[0] = [{ kind: 'bnode', value: 'unverified', scope: 'initial' }];
    const original = leasedStore(initialRows);
    const stages = [];
    let failStage = true;
    const h = harness({ load: ({ section, kind, load }) => {
        if (section !== 'types' || kind !== 'rows') return;
        if (load === 'initial') return { rowStore: original, rowCount: initialRows.length, vars: ['value'], metadata: {} };
        const stage = leasedStore([row('fresh')]);
        if (failStage) stage.failAt = 0;
        stages.push(stage);
        return { rowStore: stage, rowCount: 1, vars: ['value'], metadata: {} };
    } });
    h.controller.start();
    await until(() => h.controller.sections.types.status === 'ready');
    assert.equal(original.liveWindows(), 1, 'the current page remains reserved');
    original.failAt = 40;
    await h.controller.page('types', 'next');
    assert.equal(original.liveWindows(), 1, 'a failed local page keeps its predecessor reserved');
    delete original.failAt;
    await h.controller.retry('types', 'page');
    assert.equal(original.liveWindows(), 1, 'a successful local page swap releases its predecessor');
    await h.controller.expand('types');
    assert.equal(original.liveWindows(), 1, 'a failed staged read retains the committed window');
    assert.equal(stages[0].disposed, true);
    assert.equal(stages[0].liveWindows(), 0);
    failStage = false;
    await h.controller.expand('types');
    assert.equal(original.liveWindows(), 0, 'the replaced snapshot releases its visible window');
    assert.equal(stages[1].liveWindows(), 1, 'the committed replacement remains reserved');
    h.controller.dispose();
    assert.equal(stages[1].liveWindows(), 0, 'route disposal releases the final visible window');
});

test('a late local page read releases its stale window after a newer read commits', async () => {
    const original = leasedStore(Array.from({ length: 100 }, (_, index) => row(index)));
    const actualRead = original.readOwned;
    const pending = [];
    original.readOwned = (start, count) => start === 40
        ? new Promise(resolve => pending.push(() => actualRead(start, count).then(resolve))) : actualRead(start, count);
    const h = harness({ load: ({ section, kind, load }) => {
        if (section === 'types' && kind === 'rows' && load === 'initial') {
            return { rowStore: original, rowCount: 100, vars: ['value'], metadata: {} };
        }
    } });
    h.controller.start();
    await until(() => h.controller.sections.types.status === 'ready');
    const older = h.controller.page('types', 'next');
    const newer = h.controller.page('types', 'next');
    await until(() => pending.length === 2);
    await pending[1]();
    await newer;
    await pending[0]();
    await older;
    assert.equal(original.liveWindows(), 1, 'only the newest page remains reserved');
    assert.equal(h.controller.sections.types.start, 40);
    h.controller.dispose();
    assert.equal(original.liveWindows(), 0);
});

