test('route cancellation uses CSRF-protected keepalive POSTs for active section IDs', async () => {
    const waiting = [];
    const cancellations = [];
    context.workbench.csrfHeaders = () => ({ 'X-Workbench-CSRF': 'token' });
    const h = harness({ load: ({ url }) => new Promise(resolve => waiting.push({ url, resolve })),
        fetcher: async (url, options) => { cancellations.push({ url, options }); return {}; } });
    h.controller.start();
    await until(() => waiting.length === 8);
    h.controller.dispose();
    assert.equal(cancellations.length, 8);
    for (const cancellation of cancellations) {
        assert.equal(cancellation.options.method, 'POST');
        assert.equal(cancellation.options.keepalive, true);
        assert.equal(cancellation.options.headers['X-Workbench-CSRF'], 'token');
        assert.match(cancellation.options.body, /^action=cancel-query&query-request-id=/);
    }
});

test('section responses from a changed server never become the original repository cache', async () => {
    let identity = 'other-server';
    const h = harness({ serverIdentity: 'expected-server',
        fetcher: async () => ({ ok: true, headers: { get: name => name === 'X-Workbench-Server-Identity' ? identity : null } }),
        loadModel: async (fetcher, url, signal) => {
            await fetcher(url, { signal });
            return { rowStore: store([row('wrong-server')]), rowCount: 1, vars: ['value'], metadata: { 'explore-count': '1' } };
        } });
    h.controller.start();
    await until(() => h.controller.sections.types.status === 'error');
    assert.match(h.controller.sections.types.error, /server connection changed/i);
    assert.equal(h.controller.sections.types.store, null);
    identity = 'expected-server';
    await h.controller.retry('types', 'rows');
    assert.equal(h.controller.sections.types.status, 'ready');
    h.controller.dispose();
});

test('route mount starts section requests and renders updates without replacing the resource form', async () => {
    const requests = [];
    let renders = 0;
    context.window.fetch = async () => ({});
    context.workbench.app = { async loadModel(_fetcher, rawUrl) {
        const url = new URL(rawUrl);
        requests.push(url);
        return { rowStore: store([]), rowCount: 0, vars: ['value'], metadata: { 'explore-count': '0' } };
    } };
    context.workbench.views = { renderExploreSections() { renders++; } };
    context.workbench.paging = { setShowDataTypesCheckboxAndSetChangeEvent() {} };
    const model = { metadata: { resource: '<urn:r>', 'explore-resource': '<urn:r>' } };
    const url = new URL('https://example.test/workbench/repositories/r/explore?resource=%3Curn%3Ar%3E');
    const cleanup = explore.mount({ querySelector() { return null; } }, { model, url,
        context: { serverIdentity: 'server', repositoryId: 'r' }, runtime: {} });
    await until(() => requests.length > 0 && renders > 0);
    assert.ok(requests.every(request => request.searchParams.has('section')));
    assert.ok(model.exploreSections.types);
    cleanup();
});

test('prefixed resource stays in the form while every section uses the resolved operand', async () => {
    const requests = [];
    const input = { value: '' };
    context.window.fetch = async () => ({});
    context.workbench.app = { async loadModel(_fetcher, rawUrl) {
        requests.push(new URL(rawUrl));
        return { rowStore: store([]), rowCount: 0, vars: ['value'], metadata: { 'explore-count': '0' } };
    } };
    context.workbench.views = { renderExploreSections() {} };
    context.workbench.paging = { setShowDataTypesCheckboxAndSetChangeEvent() {} };
    const url = new URL('https://example.test/workbench/repositories/r/explore?resource=ex%3AC%2B%2B%3D1');
    const outlet = { querySelector(selector) { return selector === '#resource' ? input : null; } };
    const model = { metadata: { 'explore-resource': '<http://example.org/C++=1>' } };
    const cleanup = explore.mount(outlet, { model, url, context: {}, runtime: {} });
    await until(() => requests.length === 29);
    assert.equal(input.value, 'ex:C++=1');
    assert.ok(requests.every(request => request.searchParams.get('resource') === '<http://example.org/C++=1>'),
        'rows, counts, and scalars use the resolved operand');
    assert.equal(url.searchParams.get('resource'), 'ex:C++=1', 'navigation retains the typed operand');
    cleanup();
});

test('Explore restores and persists datatype visibility even before a resource is submitted', () => {
    let bound = 0;
    let removed = 0;
    context.workbench.paging = { setShowDataTypesCheckboxAndSetChangeEvent() { bound++; } };
    context.$ = () => ({ find() { return { off() { removed++; } }; } });
    const cleanup = explore.mount({ querySelector() { return null; } },
        { model: { metadata: {} }, url: new URL('https://example.test/explore'), context: {}, runtime: {} });
    assert.equal(bound, 1);
    cleanup();
    assert.equal(removed, 1);
});

test('reusing the route outlet resets a stale resource input from the committed URL', () => {
    context.workbench.paging = { setShowDataTypesCheckboxAndSetChangeEvent() {} };
    context.workbench.views = { renderExploreSections() {} };
    context.workbench.app = { loadModel: async () => ({ rowStore: store([]), rowCount: 0, vars: [],
        metadata: { 'explore-count': '0' } }) };
    context.window.fetch = async () => ({});
    const input = { value: 'the previous resource' };
    const outlet = { querySelector(selector) { return selector === '#resource' ? input : null; } };
    const url = new URL('https://example.test/explore?resource=ex%3AC%2B%2B%3D1');
    const cleanup = explore.mount(outlet, { model: { metadata: { 'explore-resource': '<urn:resolved>' } }, url,
        context: {}, runtime: {} });
    assert.equal(input.value, 'ex:C++=1');
    cleanup();
    input.value = 'old again';
    const emptyCleanup = explore.mount(outlet, { model: { metadata: {} }, url: new URL('https://example.test/explore'),
        context: {}, runtime: {} });
    assert.equal(input.value, '');
    emptyCleanup();
});
